import {normalizeDesktopGamepad} from './desktop-input.js';
export function createProjectedShieldControl({getGame,canControl=()=>true}={}){
 if(typeof document==='undefined')return{sync(){},dispose(){}};
 if(!document.getElementById('pw-projected-shield-style')){const style=document.createElement('style');style.id='pw-projected-shield-style';style.textContent=`#pw-projected-shield{position:fixed;left:50%;bottom:calc(env(safe-area-inset-bottom) + 78px);transform:translateX(-50%);z-index:7;display:flex;align-items:center;gap:8px;min-height:42px;padding:8px 13px;border:1px solid var(--shield-accent,#ff80b2);border-radius:12px;background:#091622df;color:#edf5ff;font:800 10px system-ui;letter-spacing:.06em;touch-action:manipulation;box-shadow:0 3px 20px #0008}#pw-projected-shield svg{width:18px;height:21px;fill:none;stroke:var(--shield-accent,#ff80b2);stroke-width:1.8}#pw-projected-shield[aria-pressed=true]{background:color-mix(in srgb,var(--shield-accent) 24%,#091622)}#pw-projected-shield:disabled{opacity:.5}#pw-projected-shield[hidden]{display:none!important}@media(max-width:700px){#pw-projected-shield{bottom:calc(env(safe-area-inset-bottom) + 72px);min-height:39px;font-size:9px;padding:7px 10px}}`;document.head.append(style);}
 const button=document.createElement('button');button.id='pw-projected-shield';button.type='button';button.hidden=true;button.innerHTML='<svg viewBox="0 0 24 28" aria-hidden="true"><path d="M12 2 22 6v9c0 5-5 9-10 11C7 24 2 20 2 15V6Z"/><path d="m7 14 3 3 7-8"/></svg><span></span>';button.setAttribute('aria-label','Déployer ou replier le bouclier du bras gauche');button.title='H : bouclier · Manette : croix directionnelle ↓';document.body.append(button);
 let disposed=false,frame=0,pads=new Map();
 const active=()=>{const g=getGame?.();return !!(g?.projectedShieldsEnabled&&g.state==='playing'&&g.player.hp>0&&canControl()&&!document.hidden&&!document.querySelector('dialog[open]'));};
 const toggle=()=>{if(active())getGame().toggleProjectedShield();sync();};
 const key=e=>{if(e.code!=='KeyH'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target?.tagName)||e.target?.isContentEditable)return;if(active()){e.preventDefault();toggle();}};
 const pointer=e=>{e.preventDefault();e.stopPropagation();toggle();};button.addEventListener('pointerdown',pointer);button.addEventListener('click',e=>{if(e.detail===0)toggle();});window.addEventListener('keydown',key);
 function sync(){const g=getGame?.();button.hidden=!active();if(!g)return;const blue=g.characterId==='lylu';button.style.setProperty('--shield-accent',blue?'#79bbff':'#ff80b2');button.disabled=(g.player.shield||0)<=0;button.setAttribute('aria-pressed',String(!!g.player.shieldDeployed));button.querySelector('span').textContent=button.disabled?'BOUCLIER EN RECHARGE':(g.player.shieldDeployed?'REPLIER':'H · BOUCLIER')+' · '+Math.ceil(g.player.shield);}
 function poll(){if(disposed)return;const next=new Map();for(const pad of navigator.getGamepads?.()||[]){if(!pad||pad.mapping==='xr-standard')continue;const normalized=normalizeDesktopGamepad(pad);if(!normalized)continue;const down=!!normalized.buttons[13]?.pressed;next.set(pad.index,down);if(down&&!pads.get(pad.index)&&active())toggle();}pads=next;sync();frame=requestAnimationFrame(poll);}frame=requestAnimationFrame(poll);
 return{sync,dispose(){disposed=true;cancelAnimationFrame(frame);window.removeEventListener('keydown',key);button.remove();pads.clear();}};
}
